insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-03','verbeterd','Dossiers','Stelposten afrekenen op eenheidsprijzen',
   'Een stelpost kon alleen op een vast bedrag of op de geboekte kosten afrekenen. Nu kan het ook op een afgesproken prijs per eenheid: je legt de eenheid en de prijs vast en vult later in hoeveel er werkelijk is uitgevoerd. Het verschil met het stelpostbedrag komt zoals altijd als een meer- of minderwerkregel op je scherm, waar de klant nog akkoord op moet geven.'),
  ('2026-09-03','verbeterd','Financieel','Opslag op geboekte kosten zelf instellen',
   'De opslag die op materiaal-, onderaannemers- en inkoopkosten wordt gerekend stond vast op 25%. Die staat nu onder Instellingen > Facturatie en is per stelpost aan te passen als daar iets anders is afgesproken.');
